  "ordered_nodes": ["V02", "V03", "V04", "V05", "V01"],
  "confidence": 0.9,
  "high_confidence_pairs": [
    {"before": "V02", "after": "V04", "confidence": 0.98},
    {"before": "V03", "after": "V04", "confidence": 0.98},
